-- Save MJ: Artifact Types (core SP call only)
DO $mj$
DECLARE
  p_ID_6df8b50a UUID;
  p_Name_6df8b50a VARCHAR(100);
  p_Description_6df8b50a TEXT;
  p_ContentType_6df8b50a VARCHAR(100);
  p_IsEnabled_6df8b50a BOOLEAN;
  p_ParentID_6df8b50a UUID;
  p_ExtractRules_6df8b50a TEXT;
  p_DriverClass_6df8b50a VARCHAR(255);
  p_Icon_6df8b50a VARCHAR(255);
  p_ContentCategory_6df8b50a VARCHAR(10);
  p_ToolLibraryClass_6df8b50a VARCHAR(100);
  p_Priority_6df8b50a INTEGER;
  p_DefaultDeliveryMode_6df8b50a VARCHAR(20);
  p_SystemSupplied_6df8b50a BOOLEAN;
BEGIN
  p_ID_6df8b50a := 'D41AB707-58F1-4413-8725-9DF31C95F4C5';
  p_Name_6df8b50a := 'ML Experiment Results';
  p_Description_6df8b50a := 'Results of a Predictive Studio experiment session authored by the Model Development Agent: the modeling goal, the leaderboard of experiment iterations, per-run metrics, feature importance, and drill-through links to each trained ML Model. Rendered by the MLExperimentResultsViewerPlugin (Angular viewer is a follow-up; falls back to the parent JSON viewer + displayMarkdown until then).';
  p_ContentType_6df8b50a := 'application/vnd.mj.ml-experiment-results';
  p_IsEnabled_6df8b50a := TRUE;
  p_ParentID_6df8b50a := 'AE674C7E-EA0D-49EA-89E4-0649F5EB20D4';
  p_ExtractRules_6df8b50a := '[{"name":"name","description":"Extracts the experiment session name/title","type":"string","standardProperty":"name","extractor":"/**\n * Extracts the name/title for ML Experiment Results artifacts.\n *\n * The canonical artifact shape is the Core `ModelingPlanSpec` (PascalCase):\n * `Goal` carries the business objective. Priority:\n * Name > Goal (truncated) > (lowercase / report fallbacks) > default.\n */\ntry {\n  const data = JSON.parse(content);\n\n  if (typeof data.Name === ''string'' && data.Name.trim()) {\n    return data.Name;\n  }\n\n  if (typeof data.Goal === ''string'' && data.Goal.trim()) {\n    return data.Goal.length > 100 ? data.Goal.substring(0, 100) + ''...'' : data.Goal;\n  }\n\n  // Fallbacks (older / LLM-authored lowercase + report shapes).\n  if (data.report && data.report.name) {\n    return data.report.name;\n  }\n  if (typeof data.goal === ''string'' && data.goal.trim()) {\n    return data.goal.length > 100 ? data.goal.substring(0, 100) + ''...'' : data.goal;\n  }\n\n  return ''ML Experiment Results'';\n} catch (e) {\n  return ''ML Experiment Results'';\n}\n"},{"name":"description","description":"Extracts a short summary/description of the experiment results","type":"string","standardProperty":"description","extractor":"/**\n * Extracts a short description/summary for ML Experiment Results artifacts.\n *\n * The canonical artifact shape is the Core `ModelingPlanSpec` (PascalCase):\n * `Goal` carries the business objective. Priority:\n * Summary > Goal > (lowercase / report fallbacks) > default.\n */\ntry {\n  const data = JSON.parse(content);\n\n  if (typeof data.Summary === ''string'' && data.Summary.trim()) {\n    return data.Summary;\n  }\n\n  if (typeof data.Goal === ''string'' && data.Goal.trim()) {\n    return data.Goal;\n  }\n\n  // Fallbacks (older / LLM-authored lowercase + report shapes).\n  if (data.report && data.report.summary) {\n    return data.report.summary;\n  }\n  if (typeof data.goal === ''string'' && data.goal.trim()) {\n    return data.goal;\n  }\n\n  return ''Results of a Predictive Studio experiment session.'';\n} catch (e) {\n  return ''Results of a Predictive Studio experiment session.'';\n}\n"},{"name":"displayMarkdown","description":"Extracts the full experiment results report in markdown (goal, leaderboard, metrics, feature importance)","type":"string","standardProperty":"displayMarkdown","extractor":"/**\n * Extracts the full experiment results report in markdown.\n *\n * The canonical artifact shape is the Core `ModelingPlanSpec` (PascalCase):\n * a `Markdown` narrative authored by the agent''s report phase. Priority:\n * Markdown > (lowercase / report fallbacks).\n */\ntry {\n  const data = JSON.parse(content);\n\n  if (typeof data.Markdown === ''string'' && data.Markdown.trim()) {\n    return data.Markdown;\n  }\n\n  // Fallbacks (older / LLM-authored lowercase + report shapes).\n  if (data.report && data.report.markdown) {\n    return data.report.markdown;\n  }\n  if (typeof data.markdown === ''string'' && data.markdown.trim()) {\n    return data.markdown;\n  }\n\n  return null;\n} catch (e) {\n  return null;\n}\n"},{"name":"bestModelId","description":"The ID of the winning ML Model for drill-through","type":"string","extractor":"/**\n * Extracts the winning ML Model ID for drill-through navigation.\n *\n * The canonical artifact shape is the Core `ModelingPlanSpec` (PascalCase):\n * a `Leaderboard` array of `{ IterationID, Metric, ModelID }` entries, best-first.\n * Priority: BestModel.ID > top Leaderboard entry''s ModelID > (lowercase / report fallbacks).\n */\ntry {\n  const data = JSON.parse(content);\n\n  // Canonical: an explicit best-model pointer (object or scalar).\n  if (data.BestModel && data.BestModel.ID) {\n    return data.BestModel.ID;\n  }\n  if (typeof data.BestModelID === ''string'') {\n    return data.BestModelID;\n  }\n\n  // Canonical: top leaderboard entry''s ModelID (PascalCase).\n  if (Array.isArray(data.Leaderboard) && data.Leaderboard.length > 0) {\n    const top = data.Leaderboard[0];\n    if (top && top.ModelID) {\n      return top.ModelID;\n    }\n  }\n\n  // Fallbacks (older / LLM-authored lowercase + report shapes).\n  if (data.report && data.report.bestModelId) {\n    return data.report.bestModelId;\n  }\n  if (typeof data.bestModelId === ''string'') {\n    return data.bestModelId;\n  }\n  if (Array.isArray(data.leaderboard) && data.leaderboard.length > 0) {\n    const topLc = data.leaderboard[0];\n    if (topLc && (topLc.modelId || topLc.ModelID)) {\n      return topLc.modelId || topLc.ModelID;\n    }\n  }\n\n  return null;\n} catch (e) {\n  return null;\n}\n"},{"name":"leaderboardSize","description":"Number of iterations on the leaderboard","type":"number","extractor":"/**\n * Extracts the number of iterations on the leaderboard.\n *\n * The canonical artifact shape is the Core `ModelingPlanSpec` (PascalCase):\n * a `Leaderboard` array. Prefer it; fall back to a lowercase `leaderboard`.\n */\ntry {\n  const data = JSON.parse(content);\n\n  if (Array.isArray(data.Leaderboard)) {\n    return data.Leaderboard.length;\n  }\n  if (Array.isArray(data.leaderboard)) {\n    return data.leaderboard.length;\n  }\n\n  return 0;\n} catch (e) {\n  return 0;\n}\n"}]';
  p_DriverClass_6df8b50a := 'MLExperimentResultsViewerPlugin';
  p_Icon_6df8b50a := 'fa-solid fa-flask-vial';
  p_ContentCategory_6df8b50a := 'Text';
  p_Priority_6df8b50a := 0;
  p_DefaultDeliveryMode_6df8b50a := 'ToolsOnly';
  p_SystemSupplied_6df8b50a := FALSE;
  PERFORM __mj."spCreateArtifactType"(p_ID := p_ID_6df8b50a, p_Name := p_Name_6df8b50a, p_Description := p_Description_6df8b50a, p_ContentType := p_ContentType_6df8b50a, p_IsEnabled := p_IsEnabled_6df8b50a, p_ParentID := p_ParentID_6df8b50a, p_ExtractRules := p_ExtractRules_6df8b50a, p_DriverClass := p_DriverClass_6df8b50a, p_Icon := p_Icon_6df8b50a, p_ContentCategory := p_ContentCategory_6df8b50a, p_ToolLibraryClass := p_ToolLibraryClass_6df8b50a, p_ToolLibraryClass_Clear := TRUE, p_Priority := p_Priority_6df8b50a, p_DefaultDeliveryMode := p_DefaultDeliveryMode_6df8b50a, p_SystemSupplied := p_SystemSupplied_6df8b50a);
END $mj$;

